import { forwardRef, useContext } from "react";
import { ThemeContext } from "@dash/Context/ThemeContext";
import { getStylesForItem, getUUID } from "@dash/Utils";
import { themeObjects } from "@dash/Utils/themeObjects";

/**
 * A card with `onClick` is a button (WCAG 2.1.1 / 4.1.2): it takes focus,
 * Enter and Space activate it, `ariaLabel` names it, and `disabled` makes it
 * inert and says so. Without `onClick` a card is plain content.
 */
function clickableProps(onClick, { disabled = false, ariaLabel } = {}) {
    if (!onClick) return {};
    return {
        role: "button",
        tabIndex: disabled ? -1 : 0,
        "aria-disabled": disabled || undefined,
        "aria-label": ariaLabel || undefined,
        "data-clickable": "true",
        onClick: disabled ? undefined : onClick,
        onKeyDown: disabled
            ? undefined
            : (e) => {
                  if (e.target !== e.currentTarget) return;
                  if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      onClick(e);
                  }
              },
    };
}

const Card = forwardRef(
    (
        {
            children,
            onClick = null,
            padding = "p-6",
            rounded = "rounded-lg",
            shadow = "shadow-sm",
            className = "",
            hover = false,
            selected = false,
            disabled = false,
            ariaLabel = null,
            testId,
            ...props
        },
        ref
    ) => {
        const { currentTheme } = useContext(ThemeContext);
        const styles = getStylesForItem(themeObjects.CARD, currentTheme, {
            ...props,
            scrollable: false,
            grow: false,
        });

        const uuid = getUUID("", "card");

        const hoverBg = styles.hoverBackgroundColor || "";
        const hoverBorder = styles.hoverBorderColor || "";
        const selectedBg = selected ? hoverBg.replace(/^hover:/, "") : "";
        const selectedBorder = selected
            ? hoverBorder.replace(/^hover:/, "")
            : "";
        const hoverStyles =
            hover && !selected
                ? `hover:shadow-md ${hoverBg} ${hoverBorder}`
                : hover
                  ? "hover:shadow-md"
                  : "";
        const clickableStyles = onClick
            ? disabled
                ? "cursor-not-allowed"
                : "cursor-pointer"
            : "";

        return (
            <div
                ref={ref}
                id={uuid}
                data-testid={testId}
                {...clickableProps(onClick, { disabled, ariaLabel })}
                className={`dr-card ${selected ? selectedBg : styles.backgroundColor} ${selected ? selectedBorder : styles.borderColor} ${styles.textColor} ${padding} ${rounded} ${shadow} transition-all duration-200 ${hoverStyles} ${clickableStyles} border ${className}`}
            >
                {children}
            </div>
        );
    }
);

