import { useContext } from "react";
import { ThemeContext } from "@dash/Context/ThemeContext";
import { getStylesForItem, getUUID } from "@dash/Utils";
import { themeObjects } from "@dash/Utils/themeObjects";
import { dispatchInputChange } from "./dispatchInputChange";
import { colorSchemeFor } from "../CodeEditor/editorTheme";
import { getStatusColors } from "@dash/Utils/statusColors";

const InputText = ({
    label = "",
    value = "",
    onChange = () => {},
    placeholder = "",
    type = "text",
    id = null,
    // Accessible name when there's no visible `label` (falls back to the placeholder).
    ariaLabel = null,
    className = "",
    inputClassName = "",
    autoFocus = false,
    disabled = false,
    // Style override props
    backgroundColor = null,
    textColor = null,
    borderColor = null,
    placeholderTextColor = null,
    focusRingColor = null,
    focusBorderColor = null,
    // Density overrides — pass alternate Tailwind class strings for
    // compact form contexts (e.g. inline filter inputs in a sidebar).
    height = "h-10",
    padding = "px-3 py-2",
    ...htmlProps
}) => {
    const { currentTheme, themeVariant } = useContext(ThemeContext);
    // A field that fails its check (aria-invalid, e.g. set by FormField's
    // error) gets the error border, so the message isn't the only sign.
    const invalid =
        htmlProps["aria-invalid"] === true ||
        htmlProps["aria-invalid"] === "true";
    const styles = getStylesForItem(themeObjects.INPUT_TEXT, currentTheme, {
        backgroundColor,
        textColor,
        borderColor:
            borderColor ||
            (invalid ? getStatusColors(themeVariant).error.accentBorder : null),
        placeholderTextColor,
        focusRingColor,
        focusBorderColor,
        scrollable: false,
        grow: false,
    });
    const labelStyles = getStylesForItem(
        themeObjects.FORM_LABEL,
        currentTheme,
        {
            textColor,
            scrollable: false,
            grow: false,
        }
    );

    const inputId = id || getUUID("", "input-text");
    const unlabeledName = label
        ? undefined
        : ariaLabel || placeholder || undefined;

    return (
        <div className={`flex flex-col space-y-1 ${className}`}>
            {label && (
                <label
                    htmlFor={inputId}
                    className={`text-sm ${labelStyles.textColor}`}
                >
                    {label}
                </label>
            )}
            <input
                {...htmlProps}
                // Native picker icons/popups (date, time, color) follow
                // the light/dark variant instead of the OS default.
                style={{
                    colorScheme: colorSchemeFor(themeVariant),
                    ...htmlProps.style,
                }}
                id={inputId}
                aria-label={unlabeledName}
                type={type}
                value={value}
                onChange={(event) => dispatchInputChange(onChange, event)}
                placeholder={placeholder}
                disabled={disabled}
                autoFocus={autoFocus}
                className={`dr-input w-full ${height} border shadow-sm ${padding} ${styles.string} focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-0 ${styles.focusRingColor || ""} ${inputClassName}`}
            />
        </div>
    );
};

export { InputText };
